H.background();
const E = P.E, B = P.B;
const vsel = B !== 0 ? E / B : 0;
H.text("Velocity selector: balance when v = E / B", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("E field (down) gives qE; B field (into page) gives qvB; they cancel only at v = E/B", 24, 52, { color: H.colors.sub, size: 13 });
const x0 = 120, x1 = H.W - 120, ymid = H.H / 2 + 10;
const halfH = 120;
// the selector chamber
H.rect(x0, ymid - halfH, x1 - x0, 2 * halfH, { stroke: H.colors.grid, width: 1, radius: 6 });
// E field arrows (pointing down) and B field crosses (into page)
for (let i = 0; i <= 8; i++) {
  const x = x0 + (x1 - x0) * i / 8;
  H.arrow(x, ymid - halfH + 8, x, ymid - halfH + 38, { color: H.colors.accent2, width: 1.5 });
  H.text("x", x, ymid + halfH - 16, { color: H.colors.violet, size: 11, align: "center", baseline: "middle" });
}
H.text("E", x0 + 14, ymid - halfH + 24, { color: H.colors.accent2, size: 12 });
H.text("B (into page)", x1 - 70, ymid + halfH - 14, { color: H.colors.violet, size: 11 });
// a test charge q>0 moving right at speed v; its vertical deflection ~ (qE - qvB)
// pick a probe speed that sweeps so the student sees too-slow / matched / too-fast
const vmax = 2 * Math.max(vsel, 1);
const v = 0.5 * vmax * (1 + Math.sin(t * 0.7));
// net upward accel sign: electric force down (=-), magnetic for +q moving right in B into page is up (=+)
// net vertical = (qvB - qE); positive => deflect up
const net = (v * B - E);
const scale = halfH / (E + Math.abs(vmax * B) + 1e-6);
const span = x1 - x0 - 60;
const px = x0 + 30 + ((t * 0.25) % 1) * span;
const ph = ((t * 0.25) % 1);
const py = ymid - net * scale * ph; // deflection accumulates across the chamber
H.line(x0 + 30, ymid, x1 - 30, ymid, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.circle(px, py, 8, { fill: H.colors.good });
H.arrow(px, py, px + 28, py, { color: H.colors.accent, width: 2 });
// force arrows on the charge
H.arrow(px, py, px, py + Math.min(40, E * scale * 0.6 + 8), { color: H.colors.accent2, width: 2 });
H.arrow(px, py, px, py - Math.min(40, v * B * scale * 0.6 + 8), { color: H.colors.violet, width: 2 });
const status = Math.abs(net) < 0.05 * (E + 1) ? "balanced -> passes straight" : (net > 0 ? "v too fast -> deflects up" : "v too slow -> deflects down");
H.text("v_select = E/B = " + vsel.toFixed(2) + " m/s   (probe v = " + v.toFixed(2) + ")  " + status, 24, 76, { color: H.colors.sub, size: 13 });
